[3635]={"Ingénierie des gnomes",{"Pour en apprendre davantage sur l'Ingénierie gnome, apporter le Manuel d'Ingénierie à Oglethorpe Obnoticus à Baie-du-Butin."}},
[3636]={"Apportez la Lumière",{"Tuer Amnennar le Porte-froid, aux Souilles de Tranchebauge, pour l’Archevêque Benedictus."}},
[3637]={"Ingénierie des gnomes",{"Pour en apprendre davantage sur l'Ingénierie gnome, apporter le Manuel d'Ingénierie à Oglethorpe Obnoticus à Baie-du-Butin."}},
[3638]={"Le Vœu du secret",{"Pour devenir un Ingénieur gobelin, cliquer avec le bouton droit sur le Vœu de secret et retourner voir une fois encore Nixx Sprocketspring dans Gadgetzan."}},
[3639]={"Montrez votre travail",{"Apporter 20 Grandes Bombes en fer, 20 Dynamites Solides et 5 Moutons Explosifs à Nixx Sprocketspring dans Gadgetzan."}},
[3640]={"Le Vœu du secret",{"Pour devenir un Ingénieur gnome, cliquer avec le bouton droit sur le Vœu de secret et retourner voir une fois encore le maître-artisan Overspark, à Ironforge."}},
[3641]={"Montrez votre travail",{"Apporter 6 Tubes de mithril, 1 Lunette de précision et 2 Leurres perfectionnés au Maître artisan Overspark à Ironforge."}},
[3642]={"Le Vœu du secret",{"Pour devenir un Ingénieur gnome, cliquer avec le bouton droit sur le Vœu de secret et retourner voir une fois encore Oglethrope Obnoticus à Baie-du-Butin."}},
[3643]={"Montrez votre travail",{"Apporter 6 Tubes de mithril, 1 Lunette de précision et 2 Cibles avancées à Oglethorpe Obnoticus à Baie-du-Butin."}},
