[3661]={"Dans les faveurs d'Elune ?",{"Collecter 15 Plumes d'Indomptable dans les Hinterlands, pour Erelas Ambersky au village de Rut'theran."}},
[3681]={"Le Tome de divinité",{"Parler à Duthorian Rall à Stormwind."}},
[3701]={"Les ruines fumantes de Thaurissan",{"Aller dans les ruines de Thaurissan, dans les Steppes ardentes. Récupérer des informations sur les Reliques de Thaurissan, puis retourner auprès de l’Historienne royale Archesonus."}},
[3702]={"Les ruines fumantes de Thaurissan",{"Écouter l'historienne royale Archesonus raconter l'histoire de Thaurissan."}},
[3721]={"Un OOX rien que pour vous",nil},
[3741]={"Le collier d'Hilary",{"Trouver le Collier d'Hilary et le rapporter à Hilary au Lakeshire."}},
[3761]={"La terre d'Un'Goro",{"Apporter 20 Echantillons d'Humus d'Un'Goro à Ghede, à Thunder Bluff."}},
[3762]={"L'aide à l'archidruide Runetotem",{"Parler à l'archidruide Hamuul Runetotem à Thunder Bluff."}},
[3763]={"L'aide à l'archidruide Staghelm",{"Parler à l'archidruide Fandral Staghelm à Darnassus."}},
[3764]={"La terre d'Un'Goro",{"Apporter 20 Echantillons d'Humus d'Un'Goro à Jenal, à Darnassus."}},
[3765]={"La dépravation au loin",{"Aller voir Gershala Nightwhisper à Auberdine."}},
[3781]={"La recherche sur la Fibre d'aurore",{"Apporter le Bon pour des graines de l'archidruide à Mathrengyl Bearwalker dans l'enclave cénarienne à Darnassus."}},
[3782]={"La recherche sur la Fibre d'aurore",{"Apporter le Bon pour des graines à Bashana Runetotem à Thunder Bluff."}},
[3783]={"Yéti ? Y es-tu ?",{"Collecter 10 Fourrures épaisses de yéti pour Umi Rumplesnicker, à Long-guet."}},
[3784]={"L'aide à l'archidruide Runetotem",{"Parler à l'archidruide Hamuul Runetotem à Thunder Bluff."}},
[3785]={"Recherches sur la Fibre d'aurore",{"Utiliser une Sacoche de printemps avec une pochette de graines de Tharlendis et deux Echantillons d'Humus d'Un'Goro pour essayer de cultiver des Fibres d'aurore.","","Apporter 10 Fibres d'aurore à Mathrengyl Bearwalker à Darnassus."}},
[3786]={"Recherches sur la Fibre d'aurore",{"Utiliser une Sacoche de printemps avec une pochette de graines de Tharlendis et deux Echantillons d'Humus d'Un'Goro pour essayer de cultiver des Fibres d'aurore.","","Apporter 10 Fibres d'aurore à Bashana Runetotem à Thunder Bluff."}},
[3787]={"La requête de Jonespyre",{"Parler à Quintis Jonespyre dans le bastion de Feathermoon."}},
[3788]={"La requête de Jonespyre",{"Parler à Quintis Jonespyre dans le bastion de Feathermoon."}},
[3789]={"Assister l'archidruide Staghelm",{"Parler à l'archidruide Fandral Staghelm à Darnassus."}},
[3790]={"Assister l'archidruide Staghelm",{"Parler à l'archidruide Fandral Staghelm à Darnassus."}},
[3791]={"Le Mystère des Fibres d'aurore",{"Apporter 10 Fibres d'aurore à Quintis Jonespyre au bastion de Feathermoon."}},
[3792]={"De la Fibre d'aurore au bastion de Feathermoon",nil},
[3801]={"Héritage Sombrefer",{"Parler à Franclorn Forgewright si obtenir une clé de la Cité majeure vous intéresse."}},
[3802]={"Héritage Sombrefer",{"Tuer Fineous Darkvire et récupérer le grand marteau, Souillefer. Apporter Souillefer au sanctuaire de Thaurissan et le placer sur la statue de Franclorn Forgewright."}},
[3803]={"Des Fibres d'aurore pour Darnassus",nil},
[3804]={"Des Fibres d'aurore pour Thunder Bluff",nil},
[3821]={"Le Rocher des Cognepeurs",{"S'aventurer dans les Steppes ardentes et découvrir ce qu'il est advenu de Sha'ni Proudtusk."}},
[3822]={nil,{"Récupérer l’Anneau de nez de Sha'ni sur Krom'Grul, et le rapporter à Thal'trak, à Kargath. Fouiller les différentes grottes et mines du Rocher des Cognepeurs."}},
[3823]={"Exterminer les Brûlentrailles",{"Tuer 15 Ogres-mages Brûlentrailles, 7 Ogres Brûlentrailles et 7 Brutes Brûlentrailles, puis retourner voir Oralius."}},
[3824]={"Le seigneur-brute Gor'tesh",{"Trouver Gor'tesh, quelque part à l’ouest du rocher des Cognepeurs. Le tuer et rapporter la Tête coupée de Gor'tesh à Oralius, dans les Steppes ardentes."}},
[3825]={"Une tête d'ogre au bout d'une pique = une fête",{"Prendre la Tête coupée de Gor'tesh et la placer au sommet du Rocher des Cognepeurs. Chercher un monticule de terre meuble pour planter la pique."}},
[3841]={"Un orphelin à la recherche d'un foyer",{"Parler à Quentin aux Mille pointes."}},
[3842]={"Une courte incubation",{"Apporter 2 Elixirs de Robustesse à Quentin, aux Mille pointes."}},
[3843]={"Un tout nouveau membre dans la famille",{"Emmenez votre Oeuf fragile de Fée fléchetteuse dans les Hinterlands et parlez à Agnar Beastamer. Dépêchez-vous, vous n’avez qu’une heure pour le trouver avant que le petit ne meure dans l’oeuf."}},
[3844]={"C'est un Secret pour tout le monde",{"Rechercher dans l'étang un indice sur l'identité du propriétaire du radeau brisé."}},
[3845]={"C'est un secret pour tout le monde",{"Examiner les objets du paquet et les apporter à leur propriétaire."}},
[3881]={"Le sauvetage de l'expédition",{"Apporter une Caisse de nourriture et de l'Equipement de recherche à Williden Marshal dans le Cratère d'Un'Goro."}},
[3882]={"Faites rouler les os",{"Apporter 8 Os de dinosaure à Spark Nilminer, au cratère d'Un'Goro."}},
[3883]={"Ecologie étrangère",{"Utiliser la Fiole de raclement pour récolter un Echantillon de paroi de la ruche dans une des nurseries de la ruche Gorishi, à l’intérieur du cratère d'Un'Goro. Chercher les chambres qui contiennent des larves suspendues.","","Apporter l’Echantillon de paroi de la ruche à Hol'anyee Marshal dans le cratère d'Un'Goro."}},
[3884]={"Le journal de Williden",{"Rapporter le Journal à Williden Marshal quelque part dans le Cratère d'Un'Goro."}},
[3901]={"Faites cliqueter les thorax !",{"Tuez 12 Squelettes Cliquethorax, puis retournez voir le prêtre des ombres Sarvis au Glas."}},
[3902]={"La chasse aux trésors",{"Fouiller Le Glas et ses alentours pour trouver 6 pièces de fournitures de récupération, et les ramener au Garde noir Saltain."}},
[3903]={nil,{"Parler à Milly Osworth."}},
[3904]={"Les vendanges de Milly",{"Apporter 8 seaux de la récolte de Milly à Milly Osworth à l'Abbaye de Northshire."}},
[3905]={"Manifeste des vendanges",{"Apporter le Manifeste des vendanges à Frère Neals dans l'Abbaye de Northshire."}},
[3906]={"Discordance des flammes",{"Partir pour la carrière dans le mont Blackrock et tuer le Grand maître Pyron. Retourner voir Thunderheart une fois votre mission accomplie."}},
[3907]={"Discordance des flammes",{"Pénétrer dans les Profondeurs de Blackrock et traquer le Seigneur Incendius. Le tuer puis donner tous les renseignements que vous pouvez trouver à Thunderheart."}},
[3908]={"C'est un Secret pour tout le monde",{"Apporter l’Epée de Linken à Donova Snowden dans le Berceau-de-l'Hiver."}},
[3909]={"L'élixir de Videre",{"Rechercher Gregan Brewspewer au nord de Feralas. Apprendre de lui comment vous pouvez acquérir l'élixir de Videre, puis retourner voir Donova Snowden, au Berceau-de-l'Hiver."}},
[3912]={"Rendez-vous à la tombe",{"Se rendre au cimetière au-dehors de Gadgetzan et boire l'élixir de Videre. Suivre le reste des instructions de Donova pour trouver Gaeriyan."}},
[3913]={"Une situation grave",{"Ressusciter, puis rechercher la pierre tombale que Gaeriyan vous a demandé de trouver."}},
[3914]={"L'épée de Linken",{"Remettre l'Epée excellente de Linken à Linken dans le cratère d'Un'Goro."}},
[3921]={nil,{"Apporter le Samophlange cassé à Wenikee Boltbucket."}},
[3922]={"Les Petites pièces",{"Apporter 15 Rondelles de métal à Wenikee Boltbucket dans les Tarides."}},
[3923]={nil,{"Apporter le Samophlange cassé à Rilli Greasygob à Orgrimmar."}},
[3924]={"Manuel du Samophlange",{"Apporter le Manuel du Samophlange à Rilli Greasygob à Orgrimmar."}},
[3941]={"Un gnome dans le besoin",{"Trouver J.D. Collie dans la caverne du refuge des Marshal."}},
[3942]={"Les souvenirs de Linken",{"Trouver Eridan Bluewind dans le sud de Gangrebois."}},
[3961]={"L'aventure de Linken",{"Apporter le Totem d'argent d'Aquementas à Linken au refuge des Marshal."}},
[3962]={"C'est dangereux d'y aller seul",{"Partir pour la crête de la Fournaise, au sud du refuge des Marshal.","","Trouver Blazerunner et utiliser le Totem pour dissiper son aura protectrice. Une fois Blazerunner vaincu, se procurer la Flamme dorée."}},
[3981]={"Le commandant Gor'shak",{"Trouver le commandant Gor'shak dans les Profondeurs de Blackrock.","","Le dessin grossier représentait également des barreaux. Peut-être devriez-vous rechercher un genre de prison."}},
[3982]={"Que se passe-t-il ?",{"Défendre Gor'shak."}},
[4001]={"Que se passe-t-il ?",{"Parler à Kharan Mighthammer et obtenir autant de renseignements que possible sur l'enlèvement de la princesse Moira Bronzebeard. Apporter ces renseignements à Thrall à Orgrimmar.","","Gor'shak a dit que Kharan était détenu dans une cellule proche."}},
[4002]={"Les Royaumes de l'est",{"Parler à Thrall si vous êtes <prêt/prête> à vous charger de la mission qu'il a prévue."}},
[4003]={"Un sauvetage royal",{"Tuer l'Empereur Thaurissan et libérer la princesse Moira Bronzebeard de son sort maléfique."}},
[4004]={"La Princesse sauvée ?",{"Retourner voir Thrall !"}},
[4005]={nil,{"Apporter le Livre d'Aquor, les Griffes argentées et le Coeur d'Arbrefer à Tanaris.","","Utiliser le Livre d'Aquor pour invoquer Aquementas.","","Après avoir terminé le totem, l’apporter à J.D. Collie au refuge des Marshal."}},
[4021]={"La contre-attaque !",{"Apporter un Morceau de la bannière de Krom'zar à Regthar Deathgate, à l'ouest de la Croisée."}},
[4022]={"Un goût de flammes",{"Montrer à Cyrus Therepentous l'Ecaille des dragons noirs que vous avez reçue de Kalaran Windblade."}},
[4023]={"Un goût de flammes",{"Montrer à Cyrus Therepentous une preuve de votre valeur.","","Vous avez le sentiment que Cyrus sait déjà que vous êtes indigne."}},
[4024]={"Un goût de flammes",{"Partir pour les Profondeurs de Blackrock et tuer Bael'Gar.","","Vous savez seulement que le géant demeure à l'intérieur des Profondeurs de Blackrock. Se souvenir d'utiliser l'Ecaille des dragons noirs altérée pour capturer l'Essence ardente.","","Apporter l'Essence ardente recouverte à Cyrus Therepentous."}},
[4041]={"L'élixir de Videre",nil},
[4061]={"La révolte des machines",{"S'aventurer dans les Steppes ardentes et récupérer 10 Fragments d'élémentaires cassés pour la Hiérophante Theodora Mulvadania.","","Theodora vous a indiqué que les golems et les élémentaires étaient la source de ces fragments."}},
[4062]={"La révolte des machines",{"Apporter l'Echantillon de fragment d'élémentaire à Lotwil Veriatus.","","Theodora vous a dit qu'il se trouvait au camp à l'est."}},
[4063]={"La révolte des machines",{"Trouver et tuer le seigneur des golems Argelmach. Rapporter sa tête à Lotwil. Collecter également 10 Noyaux d'élémentaire intacts sur les Golems ravarage et les Assemblages porteguerre qui protègent Argelmach. Vous savez cela car vous êtes médium."}},
[4081]={"TUER A VUE : nains Sombrefer",{"Pénétrer dans les Profondeurs de Blackrock et tuer les vils agresseurs !","","Le chef de guerre Goretooth veut que vous tuiez 15 Gardes Ragenclumes, 10 Gardiens Ragenclumes et 5 Fantassins Ragenclumes. Retourner le voir une fois votre mission accomplie."}},
[4082]={"TUER A VUE : Officiers de haut rang Sombrefer",{"Pénétrer dans les Profondeurs de Blackrock et tuer les vils agresseurs !","","Le Chef de guerre Goretooth veut que vous tuiez 10 Médecins Ragenclumes, 10 Soldats Ragenclumes et 10 Officiers Ragenclumes. Retourner le voir une fois votre mission accomplie."}},
[4083]={"Le Calice spectral",nil},
[4084]={"Coeur d'argent",{"Trouver 11 Griffes d'argent et 1 Cœur d'Arbrefer pour Eridan Bluewind à Gangrebois."}},
[4101]={"Purifie Gangrebois",{"Apporter 15 Ambres de sang à Arathandris Silversky à Gangrebois."}},
[4102]={"Purifie Gangrebois",{"Apporter 15 Ambres de sang à Maybess Riverbreeze à Gangrebois."}},
