[4509]={"Le calme avant la tempête",{"Apporter le Rapport de Pestlezugg sur Un'Goro à Zilzibin Drumlore, à Orgrimmar."}},
[4510]={"Le calme avant la tempête",{"Apporter le Reçu bancaire à Idriana, à la banque de Darnassus."}},
[4511]={"Le calme avant la tempête",{"Apporter le Reçu bancaire à Karus, à la banque d'Orgrimmar."}},
[4512]={"Un grand périple pour une petite gelée",{"Apporter 6 Pots de Limons maudits remplis et 6 Pots de Limons corrompus remplis à Laris Geardawdle, à Ironforge."}},
[4513]={"Un grand périple pour une petite Gelée",{"Apporter 10 Pots remplis d'échantillon pur à Laris Geardawdle, à Ironforge.","","Si vous éprouvez des difficultés à les trouver, allez voir Laris pour obtenir plus d’indices."}},
[4521]={"Gardiens sauvages",{"Trull Failbane de Gangrebois veut que vous tuiez 15 Chouettards enragés et 15 Chouettards éreintés."}},
[4542]={"Un message pour le poste de Librevent",{"Apporter le Message urgent au garde-falaise Longhorn au Poste de Librevent."}},
