[8271]={"Héros des Stormpike",nil},
[8272]={"Héros des Loups-de-givre",nil},
[8273]={"La gratitude d'Oran",nil},
[8275]={"La reconquête de Silithus",{"Parler à l'imploratrice céleste Proudhorn au Fort cénarien, en Silithus."}},
[8276]={"La reconquête de Silithus",{"Parler à l'imploratrice céleste Proudhorn au Fort cénarien, en Silithus."}},
[8277]={"Venin mortel du désert",{"Beetix Ficklespragg au Fort cénarien en Silithus veut que vous ramassiez 8 Dards de scorpide Cinglepierre et 8 Crocs de Glisseuse du sable. Retournez la voir quand vous aurez terminé."}},
[8278]={"Le dernier espoir de Noggle",{"Beetix Ficklespragg, du Fort cénarien en Silithus, veut que vous ramassiez 3 Dards de pinceurs Cinglepierre, 3 Dards d'écorcheur Cinglepierre et 3 Crocs de traqueuse des rochers."}},
[8279]={"Le lexique du Crépuscule",{"Apportez les trois chapitres du Lexique du Crépuscule à l'ermite Ortell, en Silithus."}},
[8280]={"Sécuriser les lignes d'approvisionnement",{"L'Imploratrice céleste Proudhorn au Fort cénarien en Silithus veut que vous tuiez 15 Frappeurs térébrants."}},
[8281]={"Améliorer la sécurité",{"L'Imploratrice céleste Corne-fière au Fort cénarien en Silithus veut que vous tuiez 20 Écraseurs térébrants."}},
[8282]={"La sacoche perdue de Noggle",{"Récupérez la Sacoche de Noggle dans les montagnes au sud de Silithus et rapportez-la-lui au Fort cénarien."}},
[8283]={"On recherche : Poigne-de-mort, Terreur des sables",{"Apporter la Pince de Poigne-de-mort à Vish Kozus, capitaine de la garde."}},
[8284]={"Le mystère du Crépuscule",{"La géologue Larksbane du Fort cénarien en Silithus veut que vous rassembliez 8 Fragments de Tablette du crépuscule."}},
[8285]={"Le déserteur",{"Apportez la Tablette réparée à l'ermite Ortell en Silithus."}},
[8286]={"Ce que demain apportera",{"Rendez vous dans les grottes du Temps en Tanaris et trouvez Anachronos, la progéniture de Nozdormu."}},
[8287]={"Un terrible but",{"Remettez la Transcirption décodée de la tablette au commandant Mar'alith."}},
[8288]={"Il ne peut y en avoir qu'un",{"Rapportez la Tête du seigneur des couvées Lanistaire à Baristolth des Sables changeants, au Fort cénarien en Silithus."}},
[8301]={"Le Chemin des Justes",{"Récupérez 200 Fragments de carapaces de silithides et retournez voir Baristolth."}},
[8302]={"La Main des Justes",{"Récupérez 200 Fragments de carapaces de silithides et retournez voir Baristolth."}},
[8303]={nil,{"Chercher Anachronos dans les Grottes du temps à Tanaris."}},
[8304]={"Chère Natalia",{"Le commandant Mar’alith, du Fort cénarien en Silithus, veut que vous interrogiez les habitants du Campement de Bronzebeard, qui se trouve au sud du Fort cénarien.","","Lorsque vous aurez réuni les informations demandées, retournez voir le commandant Mar’alith."}},
[8305]={"Des souvenirs oubliés depuis longtemps",{"Trouvez la Larme cristalline, en Silithus, et contemplez ses profondeurs."}},
[8306]={"L'antre de la folie",{"Le commandant Mar'alith au Fort cénarien en Silithus veut que vous retrouviez sa bien-aimée, Natalia. Selon les informations que vous avez réunies, la Ruche'Regal au sud serait l'endroit où vous pourriez trouver dame Natalia Mar'alith.","","N'oubliez pas de rendre visite aux nains au camp de Bronzebeard avant de vous aventurer dans la ruche. Ils ont peut-être d'autres tâches à vous confier et des conseils pour vous.","","Et <nom>, souvenez-vous des mots du commandant : \"Faites votre devoir...\""}},
[8307]={"Recette du désert",{"Cherchez des informations sur la façon de cuisiner la Chair de ver de sable, au camp du Marteau du crépuscule à l'ouest du Fort cénarien."}},
[8308]={"La lettre perdue de Brann Bronzebeard",{"Apporter la Lettre de Brann Bronzebeard au Campement de Bronzebeard dans le sud de Silithus."}},
[8309]={"À la poursuite des glyphes",{"Rutgar Glyphshaper, du campement de Bronzebeard en Silithus, veut que vous entriez dans Ruche’Ashi, Ruche’Zora et Ruche’Regal et que vous récupériez des reproductions des Cristaux ornés de glyphes dans chaque ruche.","","Utilisez la Trousse de transcription du géologue pour obtenir une copie correcte de ces glyphes antiques. Lorsque vous aurez terminé, retournez voir Rutgar Glyphshaper."}},
[8310]={"Déchiffrer le code",{"Obtenez un Cerveau de silithide intact provenant de la Ruche’Regal. N’importe quel silithide de cette ruche fera l’affaire."}},
[8313]={"Partager la connaissance",{"Apportez la Page de recette déchirée à Calandrath, à l’auberge du Fort cénarien."}},
[8314]={"Dévoiler le mystère",{"Rutgar Glyphshaper, du campement de Bronzebeard, veut que vous remettiez le Prisme cristallin orné de glyphes à la géologue Larksbane, au Fort cénarien en Silithus."}},
[8315]={"L'appel",{"La géologue Larksbane, au Fort cénarien en Silithus, veut que vous récupériez le Mécanisme de déverrouillage du cristal sur le Maître des clés.","","Elle vous a demandé de vous rendre près des Restes de Grakkarond, au sud du Fort cénarien, et d’y dessiner les glyphes d'appel dans le sable. Si le Maître des clés apparaît, tuez-le et récupérez le Mécanisme de déverrouillage du cristal. Ensuite, si vous avez réussi, retournez voir la géologue Larksbane.","","Elle vous a conseillé d’emmener une armée, <nom>."}},
[8316]={"Armes de guerre",nil},
[8317]={"Un coup de main à la cuisine",{"Calandrath, du Fort cénarien, a besoin d’une fournée de 10 Boulettes du desert fumées."}},
[8318]={"Communications secrètes",{"Apporter 10 Textes du crépuscule cryptés à Bor Wildmane au Fort cénarien."}},
[8319]={"Les textes du crépuscule cryptés",nil},
[8320]={"Les géoseigneurs du crépuscule",{"Tuer 10 Géoseigneurs du crépuscule, puis retourner voir Huum Wildmane au Fort cénarien."}},
[8321]={"Vyral le Vil",{"Remettre la Chevalière de Vyral à Huum Wildmane au Fort cénarien."}},
[8323]={"Les vrais croyants",{"L'ermite Ortell veut que vous lui apportiez 10 Textes du crépuscule cryptés."}},
[8324]={"Je crois encore…",nil},
[8331]={"Aurel Feuilledor",{"Parlez à Aurel Feuilledor au Fort cénarien."}},
[8332]={"Les ducs du Conseil",{"Apportez 1 Grand éclat brillant et 3 Blasons abyssaux à Aurel Goldleaf, au Fort cénarien."}},
[8333]={"Le médaillon de statut",nil},
[8341]={"Les seigneurs du conseil",{"Apportez 5 Grands éclats brillants et 3 Chevalières abyssales à Aurel Feuilledor, au Fort cénarien."}},
[8342]={"L'anneau d'autorité du crépuscule",nil},
[8343]={"La découverte de Feuilledor",{"Parlez à Aurel Feuilledor au Fort cénarien."}},
[8348]={"La chevalière des ducs",{"Apportez la Chevalière abyssale à Bor Crin-sauvage, au Fort cénarien."}},
[8349]={"Bor Crin-sauvage",{"Parlez à Bor Crin-sauvage au Fort cénarien."}},
[8351]={"Bor souhaite vous parler",{"Parlez à Bor Crin-sauvage au Fort cénarien."}},
[8352]={"Le sceptre du Conseil",{"Apportez un Sceptre abyssal à Bor Crin-sauvage, au Fort cénarien."}},
[8361]={"Des contacts abyssaux",{"Bor Wildmane, du Fort cénarien en Silithus, veut que vous détruisiez un Templier abyssal et que vous lui rameniez un Blason abyssal comme preuve de votre exploit."}},
[8362]={"Les blasons abyssaux",nil},
[8363]={"Les chevalières abyssales",nil},
[8364]={"Les sceptres abyssaux",nil},
[8365]={"Ohé, des chapeaux de pirate !",{"La Modiste arrogante veut que vous lui rapportiez 20 Chapeaux de pirate des Mers du sud au port Gentepression, en Tanaris."}},
[8366]={"Le racket des Mers du sud",{"Le chef de la sécurité Bilgewhizzle du port Gentepression, en Tanaris, veut que vous tuiez 10 Pirates des Mers du sud, 10 Flibustiers des Mers du sud, 10 Portefaix des Mers du sud et 10 Bretteurs des Mers du sud."}},
[8367]={"Pour un grand honneur",{"Apportez 3 Marques d’honneur de la vallée d’Alterac, 3 Marques d’honneur du bassin d’Arathi et 3 Marques d’honneur du goulet des Warsong à l’un des porteguerre de la Horde, devant les champs de bataille."}},
[8368]={"La bataille du goulet des Warsong",{"Apportez 3 Marques d’honneur Warsong à l’un des porteguerres de la Horde, devant les champs de bataille."}},
[8369]={"Les envahisseurs de la vallée d'Alterac",{"Apportez 3 Marques d’honneur de la vallée d’Alterac à l’un des porteguerres de la Horde, devant les champs de bataille."}},
[8370]={"La conquête du bassin d'Arathi",{"Apportez 3 Marques d’honneur du bassin d’Arathi à l’un des porteguerres de la Horde, devant les champs de bataille."}},
[8371]={"Des efforts concertés",{"Apportez 3 Marques d'honneur de la vallée d'Alterac, 3 Marques d'honneur du bassin d'Arathi et 3 Marques d'honneur du goulet des Warsong à un général de brigade de l'Alliance, devant les champs de bataille."}},
[8372]={"La lutte pour le goulet des Warsong",{"Apportez 3 Marques d'honneur du goulet des Warsong à un général de brigade de l'Alliance, devant les champs de bataille."}},
