[8936]={"Une juste compensation",{"Apportez une Ceinture de Brume-funeste et des Gants de Brume-funeste à Deliana à Forgefer."}},
[8937]={"Une juste compensation",{"Apportez une Ceinture de vaillance et une paire de Gantelets de vaillance à Deliana à Ironforge."}},
